fn same(aaa: []const u8, bbb: []const u8) bool { return std.mem.eql(u8, aaa, bbb); }
pub fn lab(conf: cfgz.Conf, key: []const u8) []const []const u8 { if (conf.labl_over.map.get(key)) |ovr| return ovr; for (PACK) |ent| { if (same(ent.key, key)) return ent.labs; } for (pak2.PACK2) |ent| { if (same(ent.key, key)) return ent.labs; } return &.{}; }
pub fn known(key: []const u8) bool { const dflt: cfgz.Conf = .{}; return lab(dflt, key).len > 0; }
pub fn pathOf(conf: cfgz.Conf, key: []const u8) []const u8 { if (conf.path_over.map.get(key)) |ovr| return ovr; for (PATHS) |pth| { if (same(pth.key, key)) return pth.path; } return ""; }
